export const deepseekPreset={base:'https://api.deepseek.com',model:'deepseek-flash'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function localOrigin(){try{const url=new URL(location.href);return ['127.0.0.1','localhost'].includes(url.hostname)?url.origin:null;}catch{return null;}}
export async function attachLocal(client){if(!localOrigin()||client.base!==localOrigin())return null;const status=await client.status();if(!status.localSetup)return null;const session=await client.request('/api/local-session');client.token=session.token;return status;}
export function openAIWizard({modal,client:current,makeClient,apply,mode,changeMode,backups,onReady}){
 let step=0,busy=false,route=localOrigin()||!current().base?'local':'remote',transport=current(),status=null,provider=null,test=null,error='',info='',draft={...deepseekPreset,key:'',remember:false},closed=false;
 const d=modal('<div id="ai-setup"></div>','连接 AI · 三步完成');d.classList.add('ai-setup-dialog');
 const panel=d.querySelector('#ai-setup'),close=()=>{closed=true;draft.key='';panel.querySelectorAll('input[type="password"]').forEach(el=>el.value='');};d.addEventListener('close',close,{once:true});
 function failText(e){if(e.name==='TypeError'||/Failed to fetch|fetch failed|Load failed/i.test(e.message))return '没有连接到后端。先双击启动本机工作台，或检查线上后端地址、HTTPS 和允许来源设置。';if(e.name==='TimeoutError')return '连接超时，请检查网络后重试。';return e.message||'连接失败，请重试';}
 function draw(){if(closed)return;panel.innerHTML=`<div class="setup-intro"><span class="setup-icon">✦</span><div><h2>接上 DeepSeek，让洞察真正运行起来</h2><p>先连接自己的工作台，再填密钥，最后用一次小请求确认。</p></div></div><ol class="setup-steps">${['运行方式','模型信息','验证与完成'].map((t,i)=>`<li class="${i===step?'active':i<step?'done':''}"><b>${i<step?'✓':i+1}</b>${t}</li>`).join('')}</ol>${error?`<div class="setup-alert error" role="alert"><b>这一步还未完成</b><p>${esc(error)}</p></div>`:''}${info?`<div class="setup-alert" role="status">${esc(info)}</div>`:''}${step===0?runtime():step===1?modelForm():verification()}<details class="setup-extra"><summary>其他设置与工作空间备份</summary><label>分析方式<select id="wizard-mode"><option value="ai" ${mode()==='ai'?'selected':''}>真实 AI</option><option value="rules" ${mode()==='rules'?'selected':''}>规则与模板演示（非 AI）</option></select></label>${backups()}</details>`;bind();}
 function runtime(){return `<h3>① 你准备在哪里运行？</h3><div class="setup-options"><button type="button" data-route="local" class="${route==='local'?'selected':''}"><b>在我的电脑上使用</b><small>适合个人体验和讲台演示 · 不需要部署云服务器</small></button><button type="button" data-route="remote" class="${route==='remote'?'selected':''}"><b>连接已经部署的后端</b><small>适合继续使用 GitHub Pages 线上地址</small></button></div>${route==='local'?`<div class="setup-local"><ol><li>在电脑的项目文件夹双击 <code>Start-MuseRadar.cmd</code>。</li><li>浏览器自动打开本机工作台；保留启动窗口。</li><li>在本机网页继续填写 DeepSeek Key。</li></ol><p>首次需要 Node.js 22 或以上。<a href="https://nodejs.org/" target="_blank" rel="noopener noreferrer">打开官方下载页 ↗</a></p>${localOrigin()?'<div class="setup-check">✓ 你正在本机网页，可以直接继续检测。</div>':'<p class="muted">线上页面不能替你启动电脑程序。拥有源码后才能使用启动器；本机和线上工作空间分别保存，可通过备份迁移。</p><a class="setup-link" href="http://127.0.0.1:8787/?setup=1" target="_blank" rel="noopener noreferrer">启动后打开本机工作台 ↗</a>'}</div>`:`<form id="runtime-form"><label>你的项目后端地址<input name="backend" type="url" placeholder="https://你的后端域名" value="${esc(transport.base||'')}" required></label><label>后端访问令牌 <small>由你自己的后端管理员提供；不是 DeepSeek Key</small><input name="operator" type="password" autocomplete="off" placeholder="仅本次会话使用"></label><p class="muted">GitHub Pages 只运行前端。没有后端时请选择本机方式；不要把 DeepSeek 地址填在这里。</p></form>`}<div class="setup-actions"><span>${route==='local'?'无需手工设置环境变量或复制令牌':'下一步会检查后端是否允许网页配置'}</span><button id="check-backend" class="primary" ${busy||route==='local'&&!localOrigin()?'disabled':''}>${busy?'正在检测…':'检测并继续 →'}</button></div>`;}
 function modelForm(){return `<div class="setup-check">✓ 项目后端已连接 <small>${esc(transport.base)}</small></div>${status?.uiConfig?`<form id="model-form"><h3>② 选择模型并填写密钥</h3><label>模型服务<select name="preset"><option value="deepseek" ${draft.base===deepseekPreset.base?'selected':''}>DeepSeek Flash（已预填）</option><option value="custom" ${draft.base!==deepseekPreset.base?'selected':''}>其他兼容服务 / 自定义</option></select></label><div class="form-grid"><label>API 根地址<input type="url" name="base" value="${esc(draft.base)}" required></label><label>模型名称<input name="model" value="${esc(draft.model)}" required></label></div><label>DeepSeek / 模型 API Key <small>${provider?.hasKey?'后端已有密钥；留空可继续使用，页面不回显。':'只发送到上方你自己的后端，不写进网页或备份。'}</small><div class="setup-password"><input name="key" type="password" autocomplete="off" spellcheck="false" placeholder="在这里粘贴 API Key" ${provider?.hasKey?'':'required'}><button type="button" id="show-key" aria-label="显示或隐藏密钥">显示</button></div></label><p class="muted">密钥路径：此页面 → ${esc(transport.base)} → ${esc(draft.base)}。<a href="https://platform.deepseek.com/api_keys" target="_blank" rel="noopener noreferrer">去 DeepSeek 创建密钥 ↗</a></p>${provider?.canRemember?`<label class="level-chip"><input name="remember" type="checkbox" ${draft.remember?'checked':''}>记住配置：仅在这台电脑用 Windows 加密保存</label>`:'<p class="muted">网页设置只对后端本次运行有效，重启后需重新填写；长期配置可由管理员设置环境变量。</p>'}<details><summary>高级选项</summary><label>最大输出 token<input name="maxTokens" type="number" min="256" max="32000" value="${draft.maxTokens||10000}"></label><p class="muted">DeepSeek 使用非思考模式完成结构化分析，减少等待。密钥不会写入 GitHub、浏览器持久存储或工作空间导出。</p></details><div class="setup-actions"><button type="button" id="setup-back">← 上一步</button><button class="primary" ${busy?'disabled':''}>${busy?'正在保存…':'保存到我的后端 →'}</button></div></form>`:`<h3>此后端暂未开放网页填写密钥</h3><p>你仍可以测试管理员已配置的模型。若需在此填写，请管理员更新后端并启用 <code>ALLOW_UI_CONFIG=1</code>，或改用本机启动器。</p><div class="setup-actions"><button id="setup-back">← 上一步</button><button id="skip-config" class="primary" ${status?.configured?'':'disabled'}>测试现有配置 →</button></div>`}`;}
 function verification(){return `<h3>③ 确认真实模型可以调用</h3><div class="setup-checklist"><div class="ok"><b>✓</b><span>后端可访问<small>${esc(transport.base)}</small></span></div><div class="${status?.configured?'ok':''}"><b>${status?.configured?'✓':'○'}</b><span>模型信息已填写<small>${esc(status?.model||draft.model)}</small></span></div><div class="${test?.ok?'ok':''}"><b>${test?.ok?'✓':'○'}</b><span>${test?.ok?'真实 API 调用已通过':'等待一次真实调用测试'}<small>${test?.ok?'已验证模型响应及 JSON 格式':'配置齐全不代表密钥、额度和模型一定可用'}</small></span></div></div><div class="setup-alert"><b>测试只发送一条固定验证消息，不上传你的评论。</b><p>会产生少量模型 token 费用；仅在你点击测试时调用，不自动收费测试。</p></div>${test?.ok?`<div class="setup-success"><b>连接成功，可以开始分析了</b><p>${esc(test.model)} · ${test.usage?.total_tokens!==undefined?'本次用量 '+esc(test.usage.total_tokens)+' tokens':'供应商未返回完整用量'} · ${esc(new Date(test.testedAt).toLocaleString())}</p></div>`:''}<div class="setup-actions"><button id="setup-back">← 修改配置</button><button id="test-model" ${busy?'disabled':''}>${busy?'正在真实调用…':test?.ok?'重新测试':'测试真实 API 连接'}</button><button class="primary" id="finish-setup" ${test?.ok?'':'disabled'}>完成，开始分析 →</button></div><p class="muted">测试通过验证连接和结构化响应，不保证每条评论的判断正确，仍需人工复核。</p>`;}
 async function connect(){if(busy)return;busy=true;error='';info='';const checkButton=panel.querySelector('#check-backend');if(checkButton){checkButton.disabled=true;checkButton.textContent='正在检测后端…';}try{if(route==='local'){transport=makeClient(localOrigin());status=await attachLocal(transport);if(!status)throw Error('这不是新版一键工作台。请双击 Start-MuseRadar.cmd，使用它打开的地址。');}else{const f=new FormData(panel.querySelector('#runtime-form')),base=String(f.get('backend')).trim().replace(/\/$/,'');if(new URL(base).hostname==='api.deepseek.com')throw Error('这里需要项目后端地址，DeepSeek 地址在下一步填写。');transport=makeClient(base,String(f.get('operator')||transport.token||''));status=await transport.status();if(status.localSetup&&transport.base!==localOrigin())throw Error('本机工作台不向线上页面发放访问权限，请打开本机地址继续配置。');if(!transport.token)throw Error('请填写项目后端访问令牌。');}await apply(transport,status);if(status.uiConfig){provider=await transport.config();draft={...draft,base:provider.base||deepseekPreset.base,model:provider.model||deepseekPreset.model,maxTokens:provider.maxTokens||10000};}step=1;}catch(e){error=failText(e);}finally{busy=false;draw();}}
 function bind(){panel.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{if(busy)return;route=b.dataset.route;error=info='';draw();});panel.querySelector('#check-backend')?.addEventListener('click',()=>{const f=panel.querySelector('#runtime-form');if(f&&!f.reportValidity())return;connect();});const form=panel.querySelector('#model-form');if(form){form.elements.key.value=draft.key;form.oninput=()=>{draft={...draft,base:form.elements.base.value,model:form.elements.model.value,key:form.elements.key.value,maxTokens:+form.elements.maxTokens.value,remember:!!form.elements.remember?.checked};test=null;};form.elements.preset.onchange=()=>{if(form.elements.preset.value==='deepseek'){draft={...draft,...deepseekPreset};draw();}};form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;error='';info='正在将配置保存到你的后端…';draw();try{const result=await transport.configure(draft);draft.key='';provider={...provider,hasKey:true};status=await transport.status();await apply(transport,status);info=result.remembered?'配置已在本机加密保存；仍需测试实际调用。':'配置已保存至后端本次运行；仍需测试实际调用。';step=2;}catch(e){error=failText(e);info='';}finally{busy=false;draw();}};panel.querySelector('#show-key').onclick=()=>{const input=form.elements.key;input.type=input.type==='password'?'text':'password';panel.querySelector('#show-key').textContent=input.type==='password'?'显示':'隐藏';};}
 panel.querySelector('#setup-back')?.addEventListener('click',()=>{if(busy)return;step=Math.max(0,step-1);error=info='';draw();});panel.querySelector('#skip-config')?.addEventListener('click',()=>{step=2;draw();});panel.querySelector('#test-model')?.addEventListener('click',async()=>{if(busy)return;busy=true;error=info='';draw();try{test=await transport.test();status=await transport.status();await apply(transport,{...status,verified:true});}catch(e){test=null;error=failText(e);}finally{busy=false;draw();}});panel.querySelector('#finish-setup')?.addEventListener('click',async()=>{await changeMode('ai');onReady();d.close();});panel.querySelector('#wizard-mode').onchange=async e=>{await changeMode(e.target.value);info=e.target.value==='rules'?'已切换规则演示，可关闭此窗口继续体验。':'已切换真实 AI 模式，需完成连接验证。';draw();};}
 draw();return d;
}
